const { execSync } = require('child_process');
const fs = require('fs');
const { resolve } = require('path');

// .docx is a zip file; the main content is in word/document.xml
// We'll use Node's zlib indirectly via a manual zip parse

const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Find local file headers (PK\x03\x04) and locate word/document.xml
// Simpler approach: use the built-in DecompressionStream or just parse the zip manually

const AdmZip = (() => {
  // Minimal zip extraction using zlib
  const zlib = require('zlib');

  // Find End of Central Directory
  let eocdOffset = -1;
  for (let i = buf.length - 22; i >= 0; i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) { eocdOffset = i; break; }
  }
  if (eocdOffset === -1) throw new Error('Not a valid ZIP');

  const cdOffset = buf.readUInt32LE(eocdOffset + 16);
  const cdEntries = buf.readUInt16LE(eocdOffset + 10);

  const files = {};
  let pos = cdOffset;
  for (let i = 0; i < cdEntries; i++) {
    const sig = buf.readUInt32LE(pos);
    if (sig !== 0x02014b50) break;
    const method = buf.readUInt16LE(pos + 10);
    const compSize = buf.readUInt32LE(pos + 20);
    const uncompSize = buf.readUInt32LE(pos + 24);
    const nameLen = buf.readUInt16LE(pos + 28);
    const extraLen = buf.readUInt16LE(pos + 30);
    const commentLen = buf.readUInt16LE(pos + 32);
    const localOffset = buf.readUInt32LE(pos + 42);
    const name = buf.slice(pos + 46, pos + 46 + nameLen).toString('utf8');

    // Read from local file header
    const lnameLen = buf.readUInt16LE(localOffset + 26);
    const lextraLen = buf.readUInt16LE(localOffset + 28);
    const dataStart = localOffset + 30 + lnameLen + lextraLen;
    const compData = buf.slice(dataStart, dataStart + compSize);

    let data;
    if (method === 0) data = compData;
    else if (method === 8) data = zlib.inflateRawSync(compData);
    else data = null;

    files[name] = data;
    pos += 46 + nameLen + extraLen + commentLen;
  }
  return files;
})();

const xml = AdmZip['word/document.xml'];
if (!xml) { console.log('No word/document.xml found in archive'); process.exit(1); }

// Strip XML tags and extract text, preserving paragraph breaks
const content = xml.toString('utf8');
// Split on paragraph tags, extract text from each
const text = content
  .replace(/<w:br[^>]*\/>/g, '\n')
  .replace(/<\/w:p>/g, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '\"')
  .replace(/&apos;/g, \"'\")
  .replace(/\n{3,}/g, '\n\n')
  .trim();

console.log(text);
"
